src = open('tmp/check.py').read()
start = src.index("    # distances: brute force over suffix lengths")
end = src.index("    # query answers")
new = '''    # distances: independent reverse BFS plus brute-force minimality probes
    rev = {}
    for s in range(n):
        for t in nxt[s]:
            rev.setdefault(t, []).append(s)
    want_dist = [None] * n
    dq = [s for s in range(n) if accept[s]]
    for s in dq:
        want_dist[s] = 0
    d = 0
    while dq:
        d += 1
        ndq = []
        for s in dq:
            for p in rev.get(s, ()):
                if want_dist[p] is None:
                    want_dist[p] = d
                    ndq.append(p)
        dq = ndq
    if want_dist != dist:
        problems.append("distance mismatch %r != %r" % (dist, want_dist))
    # brute force: no shorter continuation exists
    for s in range(n):
        limit = 6 if want_dist[s] is None else min(want_dist[s], 6)
        for L in range(limit + 1):
            hit = False
            for tup in itertools.product(range(k), repeat=L):
                suf = [alphabet[i] for i in tup]
                t = s
                for tok in suf:
                    t = nxt[t][alphabet.index(tok)]
                if accept[t]:
                    hit = True
                    break
            if hit:
                problems.append("state %d reaches acceptance in %d tokens, reported %r" % (s, L, want_dist[s]))
                break

'''
src = src[:start] + new + src[end:]
open('tmp/check.py','w').write(src)
print("ok")
